import { bigint, customType, pgView, text, timestamp } from "drizzle-orm/pg-core";

/**
 * Postgres full-text search vector. Read-only here: the search_vector columns
 * are generated by the database.
 */
export const tsvector = customType<{ data: string }>({
  dataType: () => "tsvector",
});

/** The kinds of record the search index covers. */
export const SEARCHABLE_ENTITY_TYPES = [
  "vendor",
  "tool",
  "instance",
  "capability",
  "product_team_service",
  "business_unit",
  "ownership_level",
  "page",
] as const;

export type SearchableEntityType = (typeof SEARCHABLE_ENTITY_TYPES)[number];

/**
 * One row per searchable record (published pages only).
 *
 * The view and the generated search_vector columns are created by the
 * hand-written migration drizzle/0001_search.sql, not by drizzle-kit, so this
 * is declared `.existing()` and the search_vector columns aren't in the table
 * definitions. Weights: A = title or name, B = summary or description, C = body.
 */
export const searchIndex = pgView("search_index", {
  entityType: text("entity_type").$type<SearchableEntityType>().notNull(),
  entityId: bigint("entity_id", { mode: "number" }).notNull(),
  // The record's URL identifier: slug where the table has one, otherwise key.
  slug: text("slug").notNull(),
  title: text("title").notNull(),
  summary: text("summary"),
  // The B and C text, for ts_headline snippets.
  snippetSource: text("snippet_source").notNull(),
  searchVector: tsvector("search_vector").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull(),
}).existing();
